    "question": "What is the primary effect of Section 10 of the Code of Civil Procedure (Doctrine of Res Sub Judice)?",
    "options": [
      "It dismisses the subsequently instituted suit",
      "It bars the institution of the subsequent suit",
      "It mandates the stay of the TRIAL of the subsequently instituted suit",
      "It rejects the plaint in the previously instituted suit"
    ],
    "answer": 2,
    "answerLetter": "C",
    "explanation": "Section 10 provides that no Court shall proceed with the 'trial' of any suit in which the matter in issue is directly and substantially in issue in a previously instituted suit. It stays the trial, but does not dismiss the suit or bar its institution.",
    "optionBreakdown": {
      "A": "Incorrect; Section 10 never dismisses the suit.",
      "B": "Incorrect; suit can be instituted and remains on the file.",
      "C": "Correct; Section 10 mandates stay of the TRIAL of the subsequently instituted suit.",
      "D": "Incorrect; previously instituted suit continues unhindered."
    },
